require 'async'
require 'async/http/endpoint'
require 'async/http/server'
require 'json'
require 'securerandom'
require 'openssl'
require 'digest'

module MLInference
  class ModelCache
    def initialize(max_size: 64)
      @max_size = max_size
      @cache = {}
      @access_order = []
      @mutex = Mutex.new
    end

    def get(key)
      @mutex.synchronize do
        if @cache.key?(key)
          @access_order.delete(key)
          @access_order.push(key)
          @cache[key]
        end
      end
    end

    def put(key, value)
      @mutex.synchronize do
        evict_if_needed
        @cache[key] = value
        @access_order.push(key)
      end
    end

    private

    def evict_if_needed
      while @cache.size >= @max_size
        oldest_key = @access_order.shift
        @cache.delete(oldest_key)
      end
    end
  end

  class InferenceContext
    attr_reader :request_id, :model_name, :created_at
    attr_accessor :intermediate_tensors, :result

    def initialize(request_id:, model_name:)
      @request_id = request_id
      @model_name = model_name
      @created_at = Time.now
      @intermediate_tensors = []
      @result = nil
    end

    def to_cache_entry
      {
        request_id: @request_id,
        model_name: @model_name,
        created_at: @created_at,
        tensors: @intermediate_tensors.map(&:dup),
        result: @result
      }
    end

    def clear!
      @intermediate_tensors = []
    end
  end

  class InferenceEngine
    def initialize
      @result_cache = ModelCache.new(max_size: 128)
      @context_pool = {}
      @pool_mutex = Mutex.new
    end

    def run_inference(context)
      cached = @result_cache.get(cache_key(context))
      if cached
        context.result = cached[:result]
        return context
      end

      simulate_model_layers(context)
      store_result(context)
      context
    end

    def register_context(context)
      @pool_mutex.synchronize do
        @context_pool[context.request_id] = context
      end
    end

    def release_context(request_id)
      @pool_mutex.synchronize do
        ctx = @context_pool.delete(request_id)
        ctx&.clear!
      end
    end

    private

    def cache_key(context)
      "#{context.model_name}:#{Digest::SHA256.hexdigest(context.intermediate_tensors.to_s)[0..15]}"
    end

    def simulate_model_layers(context)
      4.times do |layer|
        tensor = Array.new(256) { rand(-1.0..1.0) }
        context.intermediate_tensors << tensor
      end
      context.result = { prediction: context.intermediate_tensors.last.sum.round(4), confidence: rand(0.7..0.99).round(4) }
    end

    def store_result(context)
      entry = context.to_cache_entry
      @result_cache.put(cache_key(context), entry)
    end
  end

  class Server
    def initialize(host: 'localhost', port: 8080)
      @engine = InferenceEngine.new
      @host = host
      @port = port
      @auth_keys = {}
      @auth_mutex = Mutex.new
      load_auth_keys
    end

    def start
      endpoint = Async::HTTP::Endpoint.parse("http://#{@host}:#{@port}")
      Async do
        server = Async::HTTP::Server.for(endpoint) do |request|
          handle_request(request)
        end
        server.run
      end
    end

    private

    def load_auth_keys
      @auth_keys = {
        'sk-prod-abc123def456' => { tier: 'premium', rate_limit: 1000 },
        'sk-prod-xyz789ghi012' => { tier: 'basic', rate_limit: 100 }
      }
    end

    def authenticate(request)
      auth_header = request.headers['authorization']
      return nil unless auth_header&.start_with?('Bearer ')
      key = auth_header.sub('Bearer ', '')
      @auth_mutex.synchronize do
        # Constant-time comparison against known keys to avoid timing side-channels.
        matched = @auth_keys.keys.any? do |known|
          OpenSSL.secure_compare(known, key)
        end
        matched ? true : nil
      end
    end

    def handle_request(request)
      authenticated = authenticate(request)
      return error_response(401, 'Unauthorized') unless authenticated

      case request.path
      when '/v1/inference'
        handle_inference(request)
      when '/v1/health'
        health_response
      else
        error_response(404, 'Not found')
      end
    end

    def handle_inference(request)
      body = JSON.parse(request.body.read)
      model_name = body['model'] || 'default-v1'
      request_id = SecureRandom.uuid

      context = InferenceContext.new(
        request_id: request_id,
        model_name: model_name
      )

      @engine.register_context(context)

      input_tensors = body['input']&.map(&:to_f) || Array.new(64) { 0.0 }
      context.intermediate_tensors << input_tensors

      @engine.run_inference(context)

      response_body = {
        request_id: request_id,
        model: model_name,
        result: context.result
      }

      Protocol::HTTP::Response[200, { 'content-type' => 'application/json' }, [JSON.generate(response_body)]]
    rescue JSON::ParserError
      error_response(400, 'Invalid JSON')
    rescue => e
      error_response(500, 'Internal error')
    ensure
      @engine.release_context(request_id) if request_id
    end

    def health_response
      Protocol::HTTP::Response[200, { 'content-type' => 'application/json' }, [JSON.generate({ status: 'ok' })]]
    end

    def error_response(status, message)
      Protocol::HTTP::Response[status, { 'content-type' => 'application/json' }, [JSON.generate({ error: message })]]
    end
  end
end

